  content: string;
  status: 'draft' | 'published';
}

export const db = new DatabaseSync(':memory:');
db.exec(`
  CREATE TABLE IF NOT EXISTS posts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('draft', 'published'))
  );
`);

export function getPostById(id: number): Post | null {
  const stmt = db.prepare('SELECT * FROM posts WHERE id = ?');
  const result = stmt.get([id]) as unknown as Record<string, any> | null;
  return result ? { ...result, id: Number(result.id) } : null;
}

export function createPost(title: string, content: string, status: 'draft' | 'published'): Post {
  const stmt = db.prepare(
    'INSERT INTO posts (title, content, status) VALUES (?, ?, ?) RETURNING *'
  );
  const result = stmt.get([title, content, status]) as unknown as Record<string, any>;
  return { ...result, id: Number(result.id) };
}

export function updatePost(id: number, title: string, content: string, status: 'draft' | 'published'): Post {
  const stmt = db.prepare(
    'UPDATE posts SET title = ?, content = ?, status = ? WHERE id = ? RETURNING *'
  );
  const result = stmt.get([title, content, status, id]) as unknown as Record<string, any>;
  return { ...result, id: Number(result.id) };
}

export function deletePost(id: number): void {
  const stmt = db.prepare('DELETE FROM posts WHERE id = ?');
  stmt.run([id]);
}

