import React, { FC, useEffect, useState } from 'react';

interface Expense {
  id: number;
  category: string;
  amount: number;
  date: string;
}

interface ExpensesByCategory {
  [category: string]: Expense[];
}

type ExpensesListProps = {};

export const ExpensesList: FC<ExpensesListProps> = () => {
  const [expenses, setExpenses] = useState<Expense[]>([]);

  useEffect(() => {
    fetch('/api/expenses-api')
      .then(response => response.json())
      .then(data => setExpenses(data));
  }, []);

  const expensesByCategory: ExpensesByCategory = expenses.reduce((acc, expense) => {
    if (!acc[expense.category]) {
      acc[expense.category] = [];
    }
    acc[expense.category].push(expense);
    return acc;
  }, {} as ExpensesByCategory);

  return (
    <div>
      {Object.keys(expensesByCategory).map(category => (
        <div key={category}>
          <h2>{category}</h2>
          <ul>
            {expensesByCategory[category].map(expense => (
              <li key={expense.id}>{expense.amount} - {expense.date}</li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  );
};

import React, { FC } from 'react';

interface Expense {
  id: number;
  date: string;
  amount: number;
  category: string;
}

interface MonthlyTotalsViewProps {}

export const MonthlyTotalsView: FC<MonthlyTotalsViewProps> = () => {
  const [expenses, setExpenses] = React.useState<Expense[]>([]);

  React.useEffect(() => {
    fetch('/api/expenses-api')
      .then(response => response.json())
      .then(data => setExpenses(data));
  }, []);

  const monthlyTotals = React.useMemo(() => {
    const totals: { [key: string]: number } = {};

    expenses.forEach(expense => {
      const month = expense.date.split('-')[1];
      if (!totals[month]) {
        totals[month] = 0;
      }
      totals[month] += expense.amount;
    });

    return totals;
  }, [expenses]);

  return (
    <div>
      <h1>Monthly Totals</h1>
      <ul>
        {Object.entries(monthlyTotals).map(([month, total]) => (
          <li key={month}>Month {month}: ${total.toFixed(2)}</li>
        ))}
      </ul>
    </div>
