import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Check if the request method is DELETE or POST (assuming POST is used for removal)
  if (req.method !== 'DELETE' && req.method !== 'POST') {
    return next();
  }

  // Assuming the user information is stored in req.user and has an isAdmin property
  const isAdmin = req.user?.isAdmin;

  if (!isAdmin) {
    return res.status(403).json({ message: 'Forbidden: Only admins can perform this action.' });
  }

  next();
}

import React, { FC, useState, useEffect } from 'react';

interface Message {
  id: number;
  content: string;
  timestamp: string;
}

interface Channel {
  id: number;
  name: string;
}

export function ChatInterface(): FC {
  const [messages, setMessages] = useState<Message[]>([]);
  const [channel, setChannel] = useState<Channel | null>(null);

  useEffect(() => {
    async function fetchChannel() {
      const response = await fetch('/api/channels-api');
      const data = await response.json();
      setChannel(data);
    }

    fetchChannel();
  }, []);

  useEffect(() => {
    async function fetchMessages() {
      if (channel) {
        const response = await fetch(`/api/channels-api/${channel.id}/messages`);
        const data = await response.json();
        setMessages(data);
      }
    }

    fetchMessages();
  }, [channel]);

  return (
    <div>
      {channel ? <h1>{channel.name}</h1> : <p>Loading channel...</p>}
      <div>
        {messages.map(message => (
          <div key={message.id}>
            <p>{message.content}</p>
            <small>{message.timestamp}</small>
          </div>
        ))}
      </div>
    </div>
  );
}

